enum PMMPricing_RState { ONE, ABOVE_ONE, BELOW_ONE }

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 mtFeeRate, uint256 baseReserve, uint256 quoteReserve, uint256 baseTarget, uint256 quoteTarget, uint32 rState) public {
        // restrict to admissible domain: RState must be BELOW_ONE
        rState = uint32(bound(rState, 2, 2)); // 2 = BELOW_ONE
        // reasonable bounds for reserves and targets
        baseReserve = bound(baseReserve, 1, type(uint112).max);
        quoteReserve = bound(quoteReserve, 1, type(uint112).max);
        baseTarget = bound(baseTarget, 1, type(uint112).max);
        quoteTarget = bound(quoteTarget, 1, type(uint112).max);
        mtFeeRate = bound(mtFeeRate, 0, 1e18);
        // assume initial state: reserve >= target (the condition that triggers bug in mutant)
        vm.assume(baseReserve >= baseTarget);
        // set up contract state via internal manipulation? No vm.store allows. Instead rely on natural state.
        // We need to drive contract into a state where _RState_ == BELOW_ONE and _BASE_RESERVE_ >= _BASE_TARGET_.
        // Since we cannot set state directly, we rely on buyShares and then correctRState indirectly.
        // But adjustMtFeeRate does not change reserves/targets; it just calls correctRState.
        // The bug triggers in correctRState when RState is BELOW_ONE and _BASE_RESERVE_ >= _BASE_TARGET_.
        // So we need to get the contract into that state before calling adjustMtFeeRate.
        // However, the only way to affect these state variables is through the contract's external functions.
        // We can't guarantee the exact state, so we accept that the fuzzer will try many inputs.
        // The assertion checks that if RState was BELOW_ONE before, _BASE_TARGET_ < _BASE_RESERVE_ after.
        // But we need to capture the state before the call. We'll read RState before.
        (,, uint256 B_before, uint256 Q_before, uint256 B0_before, uint256 Q0_before, uint256 R_before) = c.getPMMStateForCall();
        // call adjustMtFeeRate with fuzzed rate
        vm.prank(c._MAINTAINER_());
        c.adjustMtFeeRate(mtFeeRate);
        // after call, read state
        (,, uint256 B_after, uint256 Q_after, uint256 B0_after, uint256 Q0_after, uint256 R_after) = c.getPMMStateForCall();
        // If RState was BELOW_ONE before the call, then after a non-reverting call, we must have _BASE_TARGET_ < _BASE_RESERVE_.
        // The mutant resets state when _BASE_RESERVE_ >= _BASE_TARGET_ in BELOW_ONE, causing _BASE_TARGET_ to become equal to _BASE_RESERVE_,
        // violating the target < reserve invariant.
        if (R_before == 2) {
            assertTrue(B0_after < B_after);
        } else {
            assertTrue(true);
        }
    }
}

